25: /**
26:  * Owns the lifecycle of every dynamic obstacle on a hole: descriptor in,
27:  * visual + collider out, deterministic `update(delta)` in between, and a
28:  * disposal path that leaves no Three.js or Rapier resources behind.
29:  */
30: export class ObstacleManager {
31:   private readonly instances = new Map<string, MutableInstance>();
32:   private readonly animated: MutableInstance[] = [];
33:   private readonly visualFactory: ObstacleVisualFactory | null;
34:   private readonly bodyFactory: ObstacleBodyFactory | null;
35:   private readonly maxDeltaSeconds: number;
36:   private disposedFlag = false;
37: 
38:   constructor(options: ObstacleManagerOptions = {}) {
39:     this.visualFactory = options.visuals ?? null;
40:     this.bodyFactory = options.bodies ?? null;
41:     const maxDelta = options.maxDeltaSeconds ?? DEFAULT_MAX_DELTA_SECONDS;
42:     this.maxDeltaSeconds = Number.isFinite(maxDelta) && maxDelta > 0 ? maxDelta : DEFAULT_MAX_DELTA_SECONDS;
43:   }
