56: 
57:   has(id: string): boolean {
58:     return this.instances.has(id);
59:   }
60: 
61:   get(id: string): ObstacleInstance | null {
62:     return this.instances.get(id) ?? null;
63:   }
64: 
65:   list(): ObstacleInstance[] {
66:     return [...this.instances.values()];
67:   }
68: 
69:   add(descriptor: ObstacleDescriptor): ObstacleInstance {
70:     if (this.disposedFlag) throw new Error('ObstacleManager is disposed');
71:     if (!descriptor.id) throw new Error('Obstacle descriptor requires a non-empty id');
72:     if (this.instances.has(descriptor.id)) throw new Error(`Duplicate obstacle id: ${descriptor.id}`);
73: 
74:     let visual: ObstacleVisual | null = null;
75:     let body: ObstacleBody | null = null;
76:     try {
77:       visual = this.visualFactory ? this.visualFactory.create(descriptor) : null;
78:       body = this.bodyFactory ? this.bodyFactory.create(descriptor) : null;
79:     } catch (error) {
80:       visual?.dispose();
81:       body?.dispose();
82:       throw error;
83:     }
84: 
85:     const basePose = basePoseOf(descriptor.transform);
86:     const instance: MutableInstance = {
87:       id: descriptor.id,
88:       descriptor,
89:       basePose,
90:       pose: clonePose(basePose),
91:       enabled: descriptor.enabled ?? true,
92:       elapsedSeconds: 0,
93:       moving: isMovingObstacle(descriptor),
94:       visual,
95:       body,
96:     };
97: 
98:     applyPose(instance);
99:     applyEnabled(instance);
100:     this.instances.set(instance.id, instance);
101:     if (instance.moving) this.animated.push(instance);
102:     return instance;
103:   }
104: 
105:   addAll(descriptors: readonly ObstacleDescriptor[]): ObstacleInstance[] {
106:     return descriptors.map((descriptor) => this.add(descriptor));
