131:     if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return;
132:     const step = Math.min(deltaSeconds, this.maxDeltaSeconds);
133:     for (const instance of this.animated) {
134:       if (!instance.enabled) continue;
135:       instance.elapsedSeconds += step;
136:       instance.pose = evaluateObstaclePose(instance.descriptor, instance.elapsedSeconds, instance.basePose);
137:       applyPose(instance);
138:     }
139:   }
