141:   /** Rewinds every obstacle to its authored pose, e.g. when a hole restarts. */
142:   reset(): void {
143:     for (const instance of this.instances.values()) {
144:       instance.elapsedSeconds = 0;
145:       instance.pose = clonePose(instance.basePose);
146:       applyPose(instance);
